package com.yjiyun.chatflows.manager;
import com.fasterxml.jackson.databind.*; import com.yjiyun.chatflows.manager.matrix.MatrixTokenProvider; import java.io.IOException;
public final class MatrixPasswordLoginSelfTest {public static void main(String[] args)throws Exception{String body=MatrixTokenProvider.passwordLoginBody("@agent-manager:local","secret-pass");JsonNode json=new ObjectMapper().readTree(body);if(!"m.login.password".equals(json.path("type").asText())||!"m.id.user".equals(json.path("identifier").path("type").asText())||!"@agent-manager:local".equals(json.path("identifier").path("user").asText())||!"secret-pass".equals(json.path("password").asText()))throw new AssertionError("Matrix password request mismatch");String token=MatrixTokenProvider.passwordLoginToken("{\"user_id\":\"@agent-manager:local\",\"access_token\":\"private-token\"}","@agent-manager:local");if(!"private-token".equals(token))throw new AssertionError("token parse failed");boolean rejected=false;try{MatrixTokenProvider.passwordLoginToken("{\"user_id\":\"@admin:local\",\"access_token\":\"human-token\"}","@agent-manager:local");}catch(IOException e){rejected=true;}if(!rejected)throw new AssertionError("Human identity accepted as manager");System.out.println("[PASS] Matrix password-login contract binds token to isolated manager identity");}}
